// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.automation.parserimport com.roshan.persona.automation.model.AutomationActionimport com.roshan.persona.automation.model.AutomationTriggerimport com.roshan.persona.automation.model.EventTypeimport com.roshan.persona.automation.model.LocationActionimport com.roshan.persona.automation.model.StateTypeimport com.roshan.persona.brain.skill.AudioStreamimport com.roshan.persona.brain.skill.RingerModeimport com.roshan.persona.brain.skill.SystemOperationimport java.time.DayOfWeekimport java.util.Calendarimport java.util.Locale/** * NOUS — Natural-language automation parser (Module 8). * * Converts the raw string slots carried by `Intent.CreateAutomation(trigger, action)` * into typed [AutomationTrigger] / [AutomationAction] instances. * * This is a REAL (not stub) parser — but it is intentionally narrow: *   - It handles the common cases users say to NOUS (time, torch, volume, *     speaking, notifications, charging, battery level, screen on/off). *   - For complex cases (geofences, compound triggers, skill IDs), it *     returns `null` so the calling skill can return `SkillOutput.NeedsInput` *     asking the user for the structured slots. * * ## Trigger grammar (case-insensitive, regex-based) * *   - `"every day at 7am"`           → TimeTrigger(7, 0, every day) *   - `"every day at 7:30 am"`       → TimeTrigger(7, 30, every day) *   - `"every weekday at 8am"`       → TimeTrigger(8, 0, Mon-Fri) *   - `"every weekend at 10am"`      → TimeTrigger(10, 0, Sat+Sun) *   - `"on monday at 9am"`           → TimeTrigger(9, 0, {MONDAY}) *   - `"at 7pm"`                     → TimeTrigger(19, 0, every day) *   - `"when charging"`              → StateTrigger(CHARGING, "true") *   - `"when battery below 20%"`     → StateTrigger(BATTERY_LEVEL, "20") *   - `"when screen turns on"`       → EventTrigger(SCREEN_ON) *   - `"when screen turns off"`      → EventTrigger(SCREEN_OFF) *   - `"when I receive a call"`      → EventTrigger(CALL_INCOMING) *   - `"when call ends"`             → EventTrigger(CALL_ENDED) *   - `"when I get an sms"`          → EventTrigger(SMS_RECEIVED) *   - `"when boot completes"`        → EventTrigger(BOOT_COMPLETED) * * ## Action grammar (case-insensitive, regex-based) * *   - `"turn on torch"` / `"torch on"`  → SystemAction(SetTorch(on=true)) *   - `"turn off torch"` / `"torch off"→ SystemAction(SetTorch(on=false)) *   - `"set volume to 50"`              → SystemAction(SetVolume(50, MEDIA)) *   - `"volume up"`                     → SystemAction(AdjustVolume(+1, MEDIA)) *   - `"volume down"`                   → SystemAction(AdjustVolume(-1, MEDIA)) *   - `"mute"`                          → SystemAction(SetRingerMode(SILENT)) *   - `"unmute"`                        → SystemAction(SetRingerMode(NORMAL)) *   - `"set brightness to 80%"`         → SystemAction(SetDisplayBrightness(0.8)) *   - `"turn on wifi"`                  → SystemAction(SetWifi(on=true)) *   - `"turn off wifi"`                 → SystemAction(SetWifi(on=false)) *   - `"turn on bluetooth"`             → SystemAction(SetBluetooth(on=true)) *   - `"turn off bluetooth"`            → SystemAction(SetBluetooth(on=false)) *   - `"turn on airplane mode"`         → SystemAction(SetAirplaneMode(on=true)) *   - `"turn on dnd"`                   → SystemAction(SetDndMode(NONE)) *   - `"turn on battery saver"`         → SystemAction(SetBatterySaver(enabled=true)) *   - `"say 'good morning'"`            → SpeakAction("good morning") *   - `"notify 'meeting in 5 minutes'"` → NotifyAction("NOUS Automation", "meeting in 5 minutes") *   - `"open app com.example.foo"`      → SystemAction(OpenApp("com.example.foo")) * * The parser is intentionally permissive — extra whitespace and minor * variations ("set volume to 50" vs "set the volume to 50") both work. * * @see <a href="docs/strategy/NOUS-Strategy-2-14-extracted.txt">§2.2 Automation</a> */object AutomationNlParser {    // ─── Trigger parsing ────────────────────────────────────────────────────    /**     * Parse a natural-language trigger string into an [AutomationTrigger].     *     * @return the parsed trigger, or `null` if the input doesn't match any     *         known pattern. Callers should fall back to `NeedsInput`.     */    fun parseTrigger(raw: String): AutomationTrigger? {        val text = raw.trim().lowercase(Locale.ROOT)        if (text.isEmpty()) return null        // Try each parser in priority order — first match wins.        return parseTimeTrigger(text)            ?: parseStateTrigger(text)            ?: parseEventTrigger(text)    }    /**     * Try parsing as a time-of-day trigger.     *     * Supports: "every day at 7am", "every weekday at 8am",     * "every weekend at 10am", "on monday at 9am", "at 7pm", "at 7:30 am".     */    private fun parseTimeTrigger(text: String): AutomationTrigger.TimeTrigger? {        // Extract day-of-week set first.        val days = when {            text.contains("every weekday") || text.contains("weekdays") ->                setOf(                    DayOfWeek.MONDAY, DayOfWeek.TUESDAY, DayOfWeek.WEDNESDAY,                    DayOfWeek.THURSDAY, DayOfWeek.FRIDAY,                )            text.contains("every weekend") || text.contains("weekends") ->                setOf(DayOfWeek.SATURDAY, DayOfWeek.SUNDAY)            text.contains("every day") || text.startsWith("at ") || text.startsWith("every day at") ->                emptySet()  // fires every day            else -> parseExplicitDays(text)        }        // Find the time pattern. Accepts "7am", "7 pm", "7:30 am", "19:30", "7:30".        val timeRegex = Regex("""\b(\d{1,2})(?::(\d{2}))?\s*(am|pm)?\b""")        val match = timeRegex.find(text) ?: return null        val hourRaw = match.groupValues[1].toIntOrNull() ?: return null        val minuteRaw = match.groupValues[2].takeIf { it.isNotBlank() }?.toIntOrNull() ?: 0        val ampm = match.groupValues[3].takeIf { it.isNotBlank() }?.lowercase(Locale.ROOT)        // Convert to 24-hour.        val hour24 = when (ampm) {            "am" -> if (hourRaw == 12) 0 else hourRaw            "pm" -> if (hourRaw == 12) 12 else hourRaw + 12            else -> hourRaw  // already 24-hour if no am/pm        }        if (hour24 !in 0..23 || minuteRaw !in 0..59) return null        return AutomationTrigger.TimeTrigger(            hour = hour24,            minute = minuteRaw,            daysOfWeek = days,        )    }    /** Parse explicit day names: "on monday", "on mon, wed, fri". */    private fun parseExplicitDays(text: String): Set<DayOfWeek> {        val days = mutableSetOf<DayOfWeek>()        if (text.contains("monday") || text.contains("mon")) days += DayOfWeek.MONDAY        if (text.contains("tuesday") || text.contains("tues") || text.contains("tue")) days += DayOfWeek.TUESDAY        if (text.contains("wednesday") || text.contains("wed")) days += DayOfWeek.WEDNESDAY        if (text.contains("thursday") || text.contains("thurs") || text.contains("thu")) days += DayOfWeek.THURSDAY        if (text.contains("friday") || text.contains("fri")) days += DayOfWeek.FRIDAY        if (text.contains("saturday") || text.contains("sat")) days += DayOfWeek.SATURDAY        if (text.contains("sunday") || text.contains("sun")) days += DayOfWeek.SUNDAY        return days    }    /**     * Try parsing as a state trigger (charging, battery level, etc.).     */    private fun parseStateTrigger(text: String): AutomationTrigger.StateTrigger? {        return when {            text.contains("charging") || text.contains("plugged in") ->                AutomationTrigger.StateTrigger(StateType.CHARGING, "true")            text.contains("unplugged") || text.contains("power disconnected") ->                AutomationTrigger.StateTrigger(StateType.POWER_DISCONNECTED, "true")            text.contains("wifi connected") || text.contains("connected to wifi") ->                AutomationTrigger.StateTrigger(StateType.WIFI_CONNECTED, "true")            text.contains("bluetooth connected") ->                AutomationTrigger.StateTrigger(StateType.BLUETOOTH_CONNECTED, "true")            text.contains("headphones connected") || text.contains("headset plugged") ->                AutomationTrigger.StateTrigger(StateType.HEADPHONES_CONNECTED, "true")            text.contains("network available") || text.contains("internet available") ->                AutomationTrigger.StateTrigger(StateType.NETWORK_AVAILABLE, "true")            else -> parseBatteryLevel(text)        }    }    /** Parse "battery below 20%" / "battery less than 30%" / "battery drops to 15%". */    private fun parseBatteryLevel(text: String): AutomationTrigger.StateTrigger? {        val regex = Regex("""battery\s+(?:below|less than|drops to|under)\s+(\d{1,3})\s*%?""")        val match = regex.find(text) ?: return null        val pct = match.groupValues[1].toIntOrNull() ?: return null        if (pct !in 1..100) return null        return AutomationTrigger.StateTrigger(StateType.BATTERY_LEVEL, pct.toString())    }    /**     * Try parsing as an event trigger (call, SMS, screen, boot).     */    private fun parseEventTrigger(text: String): AutomationTrigger.EventTrigger? {        val eventType = when {            text.contains("incoming call") || text.contains("receive a call") ||                text.contains("phone rings") || text.contains("call comes in") ->                EventType.CALL_INCOMING            text.contains("call answered") || text.contains("call picked up") ->                EventType.CALL_ANSWERED            text.contains("call ends") || text.contains("call ended") ||                text.contains("hangs up") || text.contains("hang up") ->                EventType.CALL_ENDED            text.contains("sms") || text.contains("text message") ||                text.contains("receive a message") ->                EventType.SMS_RECEIVED            text.contains("notification received") || text.contains("notif") ->                EventType.NOTIFICATION_RECEIVED            text.contains("app launched") || text.contains("open an app") ||                text.contains("app opened") ->                EventType.APP_LAUNCHED            text.contains("screen turns on") || text.contains("screen on") ||                text.contains("wake up") ->                EventType.SCREEN_ON            text.contains("screen turns off") || text.contains("screen off") ||                text.contains("screen goes dark") ->                EventType.SCREEN_OFF            text.contains("boot") || text.contains("restart") ->                EventType.BOOT_COMPLETED            text.contains("user present") || text.contains("device unlocked") ->                EventType.USER_PRESENT            else -> return null        }        return AutomationTrigger.EventTrigger(eventType, packageName = null)    }    // ─── Action parsing ─────────────────────────────────────────────────────    /**     * Parse a natural-language action string into an [AutomationAction].     *     * @return the parsed action, or `null` if the input doesn't match any     *         known pattern. Callers should fall back to `NeedsInput`.     */    fun parseAction(raw: String): AutomationAction? {        val text = raw.trim().lowercase(Locale.ROOT)        if (text.isEmpty()) return null        return parseSystemAction(text)            ?: parseSpeakAction(raw)  // preserve original case for spoken text            ?: parseNotifyAction(raw)  // preserve original case for message    }    /**     * Try parsing as a [SystemAction].     *     * Checks string-contains branches first (torch, volume, wifi, etc.),     * then regex-based branches (brightness, volume-set, open-app, open-url,     * clipboard) via the dedicated helper functions.     */    private fun parseSystemAction(text: String): AutomationAction.SystemAction? {        val op: SystemOperation? = when {            // Torch            text.contains("torch on") || text.contains("turn on torch") ||                text.contains("flashlight on") || text.contains("turn on flashlight") ->                SystemOperation.SetTorch(on = true)            text.contains("torch off") || text.contains("turn off torch") ||                text.contains("flashlight off") || text.contains("turn off flashlight") ->                SystemOperation.SetTorch(on = false)            // Volume (relative)            text.contains("mute") -> SystemOperation.SetRingerMode(RingerMode.SILENT)            text.contains("unmute") -> SystemOperation.SetRingerMode(RingerMode.NORMAL)            text.contains("volume up") || text.contains("increase volume") ->                SystemOperation.AdjustVolume(delta = 1, stream = AudioStream.MEDIA)            text.contains("volume down") || text.contains("decrease volume") ->                SystemOperation.AdjustVolume(delta = -1, stream = AudioStream.MEDIA)            // Wifi            text.contains("turn on wifi") || text.contains("enable wifi") || text.contains("wifi on") ->                SystemOperation.SetWifi(on = true)            text.contains("turn off wifi") || text.contains("disable wifi") || text.contains("wifi off") ->                SystemOperation.SetWifi(on = false)            // Bluetooth            text.contains("turn on bluetooth") || text.contains("enable bluetooth") ||                text.contains("bluetooth on") ->                SystemOperation.SetBluetooth(on = true)            text.contains("turn off bluetooth") || text.contains("disable bluetooth") ||                text.contains("bluetooth off") ->                SystemOperation.SetBluetooth(on = false)            // Airplane mode            text.contains("turn on airplane") || text.contains("enable airplane") ||                text.contains("airplane mode on") ->                SystemOperation.SetAirplaneMode(on = true)            text.contains("turn off airplane") || text.contains("disable airplane") ||                text.contains("airplane mode off") ->                SystemOperation.SetAirplaneMode(on = false)            // DnD            text.contains("turn on dnd") || text.contains("enable dnd") || text.contains("do not disturb on") ->                SystemOperation.SetDndMode(com.roshan.persona.brain.skill.DndMode.NONE)            text.contains("turn off dnd") || text.contains("disable dnd") || text.contains("do not disturb off") ->                SystemOperation.SetDndMode(com.roshan.persona.brain.skill.DndMode.ALL)            // Battery saver            text.contains("turn on battery saver") || text.contains("enable battery saver") ->                SystemOperation.SetBatterySaver(enabled = true)            text.contains("turn off battery saver") || text.contains("disable battery saver") ->                SystemOperation.SetBatterySaver(enabled = false)            // Fall through to regex-based parsers.            else -> parseBrightness(text)                ?: parseVolumeSet(text)                ?: parseOpenApp(text)                ?: parseOpenUrl(text)                ?: parseClipboard(text)        }        if (op == null) return null        return AutomationAction.SystemAction(op)    }    /** Parse "brightness to 80%" / "brightness 80%". */    private fun parseBrightness(text: String): SystemOperation? {        val m = Regex("""brightness\s+(?:to\s+)?(\d{1,3})\s*%?""").find(text) ?: return null        val pct = m.groupValues[1].toIntOrNull() ?: return null        if (pct !in 0..100) return null        return SystemOperation.SetDisplayBrightness(level = pct / 100f)    }    /** Parse "set volume to 50" / "volume 50". */    private fun parseVolumeSet(text: String): SystemOperation? {        val m = Regex("""(?:set\s+)?volume\s+(?:to\s+)?(\d{1,3})""").find(text) ?: return null        val lvl = m.groupValues[1].toIntOrNull() ?: return null        if (lvl !in 0..100) return null        return SystemOperation.SetVolume(level = lvl, stream = AudioStream.MEDIA)    }    /** Parse "open app com.example.foo". */    private fun parseOpenApp(text: String): SystemOperation? {        val m = Regex("""open\s+app\s+([a-z0-9_.]+)""").find(text) ?: return null        val pkg = m.groupValues[1]        if (!pkg.contains(".")) return null        return SystemOperation.OpenApp(packageName = pkg)    }    /** Parse "open https://example.com". */    private fun parseOpenUrl(text: String): SystemOperation? {        val m = Regex("""open\s+(?:url\s+)?(https?://\S+)""").find(text) ?: return null        return SystemOperation.OpenUrl(url = m.groupValues[1])    }    /** Parse "copy 'text to clipboard'". */    private fun parseClipboard(text: String): SystemOperation? {        val m = Regex("""copy\s+(?:to\s+clipboard\s+)?["“](.+?)["”]""").find(text) ?: return null        return SystemOperation.CopyToClipboard(text = m.groupValues[1])    }    /**     * Try parsing as a [SpeakAction].     *     * Accepts: `say "good morning"`, `say 'hi'`, `speak "hello world"`.     */    private fun parseSpeakAction(raw: String): AutomationAction.SpeakAction? {        val regex = Regex("""(?:say|speak|tell me)\s+["“'](.+?)["”']""", RegexOption.IGNORE_CASE)        val match = regex.find(raw) ?: return null        val text = match.groupValues[1].trim()        if (text.isEmpty()) return null        return AutomationAction.SpeakAction(text = text)    }    /**     * Try parsing as a [NotifyAction].     *     * Accepts: `notify "message"`, `notify 'message'`, `show notification "message"`.     */    private fun parseNotifyAction(raw: String): AutomationAction.NotifyAction? {        val regex = Regex("""(?:notify|show notification|show notif)\s+["“'](.+?)["”']""", RegexOption.IGNORE_CASE)        val match = regex.find(raw) ?: return null        val message = match.groupValues[1].trim()        if (message.isEmpty()) return null        return AutomationAction.NotifyAction(            title = "NOUS Automation",            message = message,        )    }    // ─── Helpers ────────────────────────────────────────────────────────────    /**     * Format a trigger for human display (used by ListAutomationsSkill).     */    fun describeTrigger(trigger: AutomationTrigger): String = when (trigger) {        is AutomationTrigger.TimeTrigger -> {            val time = String.format(Locale.ROOT, "%02d:%02d", trigger.hour, trigger.minute)            val days = when {                trigger.firesEveryDay -> "every day"                trigger.daysOfWeek.size == 7 -> "every day"                trigger.daysOfWeek == setOf(                    DayOfWeek.MONDAY, DayOfWeek.TUESDAY, DayOfWeek.WEDNESDAY,                    DayOfWeek.THURSDAY, DayOfWeek.FRIDAY,                ) -> "weekdays"                trigger.daysOfWeek == setOf(DayOfWeek.SATURDAY, DayOfWeek.SUNDAY) -> "weekends"                else -> trigger.daysOfWeek.joinToString(", ") { it.name.lowercase(Locale.ROOT) }            }            "At $time ($days)"        }        is AutomationTrigger.LocationTrigger -> {            val act = when (trigger.action) {                LocationAction.ENTER -> "arrive at"                LocationAction.EXIT -> "leave"                LocationAction.DWELL -> "stay at"            }            "When I $act (${trigger.latitude}, ${trigger.longitude}) ±${trigger.radiusMeters}m"        }        is AutomationTrigger.EventTrigger -> {            val pkg = trigger.packageName?.let { " from $it" } ?: ""            "When ${trigger.eventType.name.lowercase(Locale.ROOT).replace('_', ' ')}$pkg"        }        is AutomationTrigger.StateTrigger -> {            "When ${trigger.stateType.name.lowercase(Locale.ROOT).replace('_', ' ')} = ${trigger.value}"        }        is AutomationTrigger.CompoundTrigger -> {            val op = if (trigger.operator == com.roshan.persona.automation.model.LogicalOperator.AND) "AND" else "OR"            trigger.triggers.joinToString(" $op ") { describeTrigger(it) }        }    }    /**     * Format an action for human display (used by ListAutomationsSkill).     */    fun describeAction(action: AutomationAction): String = when (action) {        is AutomationAction.SystemAction -> "System: ${action.operation::class.simpleName}"        is AutomationAction.SkillAction -> "Run skill '${action.skillId}'"        is AutomationAction.SpeakAction -> "Say \"${action.text}\""        is AutomationAction.NotifyAction -> "Notify: ${action.title} — ${action.message}"        is AutomationAction.ChainAction -> action.actions.joinToString(" → ") { describeAction(it) }    }    /**     * Compute the epoch-millis delay until the next firing of a [TimeTrigger],     * starting from [now] (default = current time).     *     * If today's fire time has already passed, the next fire is tomorrow at     * the same time. Day-of-week filtering is respected — if the trigger     * doesn't fire today, the delay is computed to the next valid day.     */    fun nextFireDelayMs(        trigger: AutomationTrigger.TimeTrigger,        now: Calendar = Calendar.getInstance(),    ): Long {        val target = (now.clone() as Calendar).apply {            set(Calendar.HOUR_OF_DAY, trigger.hour)            set(Calendar.MINUTE, trigger.minute)            set(Calendar.SECOND, 0)            set(Calendar.MILLISECOND, 0)        }        // If today's slot already passed, or today is not a firing day, advance.        var advanced = 0        while (target.before(now) || !trigger.firesOn(                DayOfWeek.of(target.get(Calendar.DAY_OF_WEEK) - 1)            )        ) {            target.add(Calendar.DAY_OF_YEAR, 1)            advanced++            if (advanced > 14) break  // safety — should never happen        }        return target.timeInMillis - now.timeInMillis    }}